const fs = require('fs');
const querystring = require('querystring');

// Read the .env.test file
const envContents = fs.readFileSync('.env.test', 'utf8');

// URL-encode the contents
const encodedContents = encodeURIComponent(envContents);
console.log("URL-encoded contents:", encodedContents);
console.log("\nFull URL: http://localhost:47301/badge.png?d=" + encodedContents);

// Test the URL
const http = require('http');
const url = "http://localhost:47301/badge.png?d=" + encodedContents;

console.log("\nTesting URL...");

// Make a simple request to verify connectivity
const req = http.get(url, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log(`Content-Type: ${res.headers['content-type']}`);
  res.on('data', (chunk) => {
    console.log("Received response (showing first 200 chars):", chunk.toString().substring(0, 200));
  });
});

req.on('error', (err) => {
  console.error("Error:", err.message);
});

const fs = require('fs');

// Read .env.test content
const envContent = fs.readFileSync('.env.test', 'utf8');

// URL encode the content
const encodedContent = encodeURIComponent(envContent);

console.log('Encoded content:');
console.log(encodedContent);

// Construct badge URL
const badgeUrl = `http://localhost:47301/badge.png?d=${encodedContent}`;
console.log('\nBadge URL:');
console.log(badgeUrl);

// Construct markdown image
const markdownImage = `![status](${badgeUrl})`;
console.log('\nMarkdown image tag:');
console.log(markdownImage);

